if (sourceEvent && !identity.matches) {
  state.pickupGuideConflicts = {...(state.pickupGuideConflicts || {}), [sourceEventId]:{
    eventId:sourceEventId, day:sourceDay, guideId:guide.id,
    issues:identity.failures, status:'requires_driver_review',
  }};
}
